{
  "findings": [
    {
      "check_id": "CKV2_AWS_73",
      "title": "SQS queue does not use a customer-managed KMS key",
      "resource": "aws_sqs_queue.pass2",
      "severity": "MEDIUM",
      "explanation": "The queue uses SQS-managed server-side encryption rather than a customer-managed KMS key, limiting control over key rotation, access policies, and auditing."
    }
  ],
  "patched_code": "resource \"aws_kms_key\" \"pass2\" {\n  description         = \"KMS key for the pass2 SQS queue\"\n  enable_key_rotation = true\n}\n\nresource \"aws_sqs_queue\" \"pass2\" {\n  name              = \"unencrypted-queue\"\n  kms_master_key_id = aws_kms_key.pass2.arn\n}\n",
  "fix_summary": "Added a customer-managed KMS key with automatic rotation and configured the SQS queue to use it instead of SQS-managed encryption."
}
